 [Fact]public async Task Monthly_evidence_coach_needs_current_group_assignment_even_for_readonly_export()
 {
  using var coach=await Mobile(AcademyRole.Coach);await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();var opts=await coach.GetFromJsonAsync<JsonElement>("/api/v1/evaluations/options");var id=opts.GetProperty("enrollments")[0].GetProperty("id").GetGuid();var e=await FreshSkillChild(db,await db.SportEnrollments.AsNoTracking().SingleAsync(e=>e.Id==id));var hash=Academy.Api.Mobile.MobileAuthenticationHandler.Hash(coach.DefaultRequestHeaders.Authorization!.Parameter!);var member=await db.MobileSessions.Where(s=>s.AccessTokenHash==hash).Select(s=>s.MembershipId).SingleAsync();var assignment=await db.StaffGroupAssignments.SingleAsync(a=>a.AcademyMembershipId==member&&a.TrainingGroupId==e.TrainingGroupId&&a.IsActive);var url=$"/api/v1/evaluations/monthly/enrollments/{e.Id}";
  try{(await coach.GetAsync(url+"?format=csv")).EnsureSuccessStatusCode();assignment.IsActive=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.NotFound,(await coach.GetAsync(url)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await coach.GetAsync(url+"?format=text")).StatusCode);}finally{assignment.IsActive=true;await db.SaveChangesAsync();}
 }
 [Fact]public async Task Monthly_evidence_read_grant_and_branch_sport_are_required_for_export_too()=>await DelegateFixture(async(owner,admin,db,group,member)=>{
  var e=await FreshSkillChild(db,new(){AcademyId=group.AcademyId,SportId=group.SportId,BranchId=group.BranchId,TrainingGroupId=group.Id});var grant=await db.StaffActionGrants.SingleOrDefaultAsync(g=>g.MembershipId==member&&g.Module=="evaluations");var prior=grant==null?null:JsonSerializer.Serialize(grant);grant??=new(){Id=Guid.NewGuid(),AcademyId=group.AcademyId,MembershipId=member,Module="evaluations"};if(prior==null)db.StaffActionGrants.Add(grant);
  try{grant.IsActive=true;grant.Read=true;grant.Add=false;grant.Edit=false;grant.Delete=false;await db.SaveChangesAsync();var url=$"/api/v1/evaluations/monthly/enrollments/{e.Id}";(await admin.GetAsync(url+"?format=csv")).EnsureSuccessStatusCode();var branch=await db.MembershipBranchAccesses.SingleAsync(a=>a.MembershipId==member&&a.BranchId==group.BranchId);branch.IsActive=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.NotFound,(await admin.GetAsync(url+"?format=text")).StatusCode);branch.IsActive=true;var sport=await db.MembershipSportAccesses.SingleAsync(a=>a.MembershipId==member&&a.SportId==group.SportId);sport.IsActive=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.NotFound,(await admin.GetAsync(url+"?format=csv")).StatusCode);sport.IsActive=true;grant.Read=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.Forbidden,(await admin.GetAsync(url)).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await admin.GetAsync(url+"?format=csv")).StatusCode);}
  finally{if(prior==null)db.StaffActionGrants.Remove(grant);else db.Entry(grant).CurrentValues.SetValues(JsonSerializer.Deserialize<Academy.Infrastructure.Tenancy.StaffActionGrant>(prior)!);await db.SaveChangesAsync();}
 });
 [Fact]public async Task Monthly_evidence_certificate_is_issued_evidence_not_an_automatic_promotion_and_withdrawal_is_live()
 {
  using var owner=await Staff();using var coach=await Mobile(AcademyRole.Coach);using var family=await Mobile(AcademyRole.Guardian);await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();var(f,rid,target)=await PromotionSetup(owner,coach,db);(await Send(owner,$"{Technical}/{rid}/promotion",await PromotionBody(owner,rid,target))).EnsureSuccessStatusCode();var source=await db.PlayerLevelReviews.AsNoTracking().SingleAsync(r=>r.SportEnrollmentId==f.Enrollment&&r.TechnicalDecisionId!=null);var id=await LessonId(await Send(owner,$"{Certificates}/sources/{source.Id}/issue",new CertificateIssueWrite(source.Version,Guid.NewGuid())));var url=$"/api/v1/guardian/children/{f.Player}/monthly?enrollmentId={f.Enrollment}";var report=await family.GetFromJsonAsync<JsonElement>(url);Assert.Equal(1,report.GetProperty("counts").GetProperty("certificates").GetInt32());Assert.Contains(report.GetProperty("items").EnumerateArray(),x=>x.GetProperty("id").GetGuid()==id&&x.GetProperty("state").GetString()=="Issued");var c=await db.PlayerAchievementCertificates.AsNoTracking().SingleAsync(c=>c.Id==id);(await Send(owner,$"{Certificates}/{id}/withdraw",new CertificateWithdrawWrite(c.Version,null,Guid.NewGuid()))).EnsureSuccessStatusCode();Assert.Contains("شهادة مسحوبة",await family.GetStringAsync(url+"&format=csv"));
 }
 [Fact]public async Task Monthly_evidence_is_live_paginated_exportable_after_expiry_and_rechecks_family_and_tenant()
 {
  using var owner=await Staff();using var family=await Mobile(AcademyRole.Guardian);using var foreign=await Staff(DemoSeed.FutureOwnerEmail);
  await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();
  var link=await db.GuardianPlayerLinks.FirstAsync(l=>l.IsActive&&l.Guardian.User.PhoneNumber==DemoSeed.GuardianPhone&&l.Player.IsActive);
  var source=await db.SportEnrollments.AsNoTracking().FirstAsync(e=>e.PlayerId==link.PlayerId&&e.IsActive);var e=await FreshSkillChild(db,source,link.GuardianId);
  var today=await AttendanceCalendar.TodayAsync(e.AcademyId,db,TimeProvider.System);var month=today.ToString("yyyy-MM");var money=await owner.GetStringAsync("/api/v1/reports/financial?from=2026-09-01&to=2026-09-28");var notices=await db.AcademyNotices.CountAsync();
  var badgeUrl=$"{Badges}/enrollments/{e.Id}";var bd=(await owner.GetFromJsonAsync<JsonElement>(badgeUrl)).GetProperty("enrollments")[0];Guid first=default;
  for(var n=0;n<26;n++){var rule=await LessonId(await Send(owner,Badges+"/rules",BadgeRule(e.SportId)));var g=await LessonId(await Send(owner,badgeUrl+"/grant",new BadgeGrantWrite(rule,bd.GetProperty("enrollmentVersion").GetUInt32(),today,n==0?" =SUM(A1)":null,Guid.NewGuid())));if(n==0)first=g;}
  var staff=$"/api/v1/evaluations/monthly/enrollments/{e.Id}?month={month}";var child=$"/api/v1/guardian/children/{e.PlayerId}/monthly?enrollmentId={e.Id}&month={month}";
  var report=await family.GetFromJsonAsync<JsonElement>(child);Assert.Equal(26,report.GetProperty("counts").GetProperty("badges").GetInt32());Assert.Equal(25,report.GetProperty("items").GetArrayLength());Assert.True(report.GetProperty("hasMore").GetBoolean());Assert.Equal(1,(await family.GetFromJsonAsync<JsonElement>(child+"&page=1")).GetProperty("items").GetArrayLength());
  Assert.Equal(report.GetProperty("items").GetRawText(),(await owner.GetFromJsonAsync<JsonElement>(staff)).GetProperty("items").GetRawText());
  var csv=await family.GetAsync(child+"&format=csv");csv.EnsureSuccessStatusCode();Assert.Equal("text/csv",csv.Content.Headers.ContentType!.MediaType);var content=await csv.Content.ReadAsStringAsync();Assert.Equal(28,content.Split("\r\n").Length);Assert.Contains("\"'=SUM(A1)\"",content);Assert.Equal(content,(await family.GetFromJsonAsync<JsonElement>(child+"&format=text")).GetProperty("text").GetString());Assert.Contains("no-store",csv.Headers.CacheControl!.ToString());
  var grant=await db.PlayerBadgeGrants.AsNoTracking().SingleAsync(g=>g.Id==first);(await Send(owner,$"{Badges}/grants/{first}/revoke",new BadgeActionWrite(grant.Version,null,Guid.NewGuid()))).EnsureSuccessStatusCode();Assert.Contains("شارة مسحوبة",await family.GetStringAsync(child+"&format=csv"));
  var past=today.AddMonths(-1).ToString("yyyy-MM");Assert.Equal(0,(await family.GetFromJsonAsync<JsonElement>(child.Replace(month,past))).GetProperty("counts").GetProperty("badges").GetInt32());Assert.Equal(HttpStatusCode.BadRequest,(await family.GetAsync(child.Replace(month,today.AddMonths(1).ToString("yyyy-MM")))).StatusCode);
  Assert.Equal(HttpStatusCode.NotFound,(await foreign.GetAsync(staff)).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await family.GetAsync(child.Replace(e.PlayerId.ToString(),Guid.NewGuid().ToString()))).StatusCode);Assert.Equal(HttpStatusCode.NotFound,(await family.GetAsync(child.Replace(e.Id.ToString(),source.Id.ToString()))).StatusCode);
  // Fresh child has no paid subscription: access must not be held hostage to renewal.
  Assert.False(await db.SubscriptionPeriods.AnyAsync(p=>p.SportEnrollmentId==e.Id));Assert.Equal(money,await owner.GetStringAsync("/api/v1/reports/financial?from=2026-09-01&to=2026-09-28"));Assert.Equal(notices,await db.AcademyNotices.CountAsync());
  var ownLink=await db.GuardianPlayerLinks.SingleAsync(l=>l.PlayerId==e.PlayerId);ownLink.IsActive=false;await db.SaveChangesAsync();Assert.Equal(HttpStatusCode.NotFound,(await family.GetAsync(child+"&format=csv")).StatusCode);
 }
 [Fact]public async Task Monthly_evidence_published_skill_keeps_measurement_protocol_and_history_without_averaging()
 {
  using var owner=await Staff();using var family=await Mobile(AcademyRole.Guardian);await using var scope=factory.Services.CreateAsyncScope();var db=scope.ServiceProvider.GetRequiredService<FoundationDbContext>();var link=await db.GuardianPlayerLinks.FirstAsync(l=>l.IsActive&&l.Guardian.User.PhoneNumber==DemoSeed.GuardianPhone&&l.Player.IsActive);var source=await db.SportEnrollments.AsNoTracking().FirstAsync(e=>e.PlayerId==link.PlayerId&&e.IsActive);var e=await FreshSkillChild(db,source,link.GuardianId);var(c,level,_)=await SkillDefinition(owner,e.SportId);(await Send(owner,$"/api/v1/people/enrollments/{e.Id}/placement-level",new{levelId=level},true)).EnsureSuccessStatusCode();await PublishSkills(owner,c);var p=await LessonId(await Send(owner,$"{Skills}/enrollments/{e.Id}/skill-plan",new SkillPlanWrite(c,Guid.NewGuid())));var d=await owner.GetFromJsonAsync<JsonElement>($"{Skills}/plans/{p}");var r=d.GetProperty("skills")[1].GetProperty("requirement").GetProperty("id").GetGuid();var today=DateOnly.Parse(d.GetProperty("asOfDate").GetString()!);
  (await Send(owner,$"{Skills}/plans/{p}/reviews",new SkillReviewWrite(r,"Learning",3,today,"ثلاث تمريرات اصطناعية بنفس البروتوكول",Guid.NewGuid()))).EnsureSuccessStatusCode();(await Send(owner,$"{Skills}/plans/{p}/reviews",new SkillReviewWrite(r,"Mastered",8,today,"ثماني تمريرات بمراجعة بشرية",Guid.NewGuid()))).EnsureSuccessStatusCode();
  var report=await family.GetFromJsonAsync<JsonElement>($"/api/v1/guardian/children/{e.PlayerId}/monthly?enrollmentId={e.Id}");Assert.Equal(2,report.GetProperty("counts").GetProperty("skills").GetInt32());Assert.All(report.GetProperty("items").EnumerateArray(),x=>{Assert.Equal("Count",x.GetProperty("unit").GetString());Assert.Equal(p,x.GetProperty("planId").GetGuid());});Assert.Contains(report.GetProperty("items").EnumerateArray(),x=>x.GetProperty("value").GetDecimal()==3);Assert.Contains(report.GetProperty("items").EnumerateArray(),x=>x.GetProperty("value").GetDecimal()==8);Assert.False(report.TryGetProperty("power",out _));
 }
}
